<script setup>
import {onMounted,ref} from "vue";import {NButton,NEmpty,NInput,NModal,NSelect,NTag,NForm,NFormItem,NAlert,useMessage,useDialog} from "naive-ui";
import PageShell from "../components/PageShell.vue";import Panel from "../components/Panel.vue";import {imApi,skillsApi} from "../api.js";import {can} from "../access.js";
const message=useMessage(),dialog=useDialog(),bots=ref([]),loading=ref(false),error=ref(""),busy=ref(false),showCreate=ref(false),editing=ref(null),targetBot=ref(null),staffId=ref(""),conversationId=ref(""),sendResult=ref(""),outbox=ref([]),skills=ref([]);
const blank=()=>({name:"",platform:"dingtalk",appKey:"",appSecret:"",robotCode:"",callbackToken:"",aesKey:"",workflowId:"auto-flow"});const draft=ref(blank());
const platforms=[{label:"钉钉",value:"dingtalk"},{label:"企业微信自建应用",value:"wecom"}];
async function load(){loading.value=true;error.value="";try{bots.value=await imApi.bots();skills.value=[{label:"自动编排",value:"auto-flow"},...(await skillsApi.list()).filter(s=>s.id!=='auto-flow').map(s=>({label:s.name,value:s.id}))];}catch(e){error.value=e.message;}finally{loading.value=false;}}
function edit(item){editing.value=item?.id??null;draft.value={...blank(),...(item?{name:item.name,platform:item.platform,appKey:item.appKey,robotCode:item.robotCode,workflowId:item.workflowId}:{})};showCreate.value=true;}
async function save(){busy.value=true;try{const d=draft.value;const input={name:d.name.trim(),platform:d.platform,appKey:d.appKey.trim(),robotCode:d.robotCode.trim(),workflowId:d.workflowId};if(!input.name||!input.appKey||!input.robotCode)throw Error("请填写名称、应用标识和机器人编号");for(const key of ['appSecret','callbackToken','aesKey'])if(d[key].trim()||!editing.value)input[key]=d[key].trim();if(!editing.value&&(!input.appSecret||!input.callbackToken))throw Error("请填写应用密钥和回调 Token");if(!editing.value&&d.platform==='wecom'&&!input.aesKey)throw Error("企业微信必须填写 EncodingAESKey");if(editing.value)await imApi.patch(editing.value,input);else await imApi.create(input);showCreate.value=false;draft.value=blank();await load();message.success("机器人配置已保存");}catch(e){message.error(e.message);}finally{busy.value=false;}}
async function toggle(item){busy.value=true;try{await imApi.patch(item.id,{enabled:!item.enabled});await load();}catch(e){message.error(e.message);}finally{busy.value=false;}}
function remove(item){dialog.warning({title:"删除机器人",content:`确定删除「${item.name}」及其外部会话映射？`,positiveText:"删除",negativeText:"取消",onPositiveClick:async()=>{try{await imApi.remove(item.id);await load();}catch(e){message.error(e.message);return false;}}});}
function callback(item){return `${location.origin}/api/im/${item.platform==='wecom'?'wecom':'dingtalk'}/callback?botId=${encodeURIComponent(item.id)}`;}
async function copy(item){try{await navigator.clipboard.writeText(callback(item));message.success("回调地址已复制");}catch{message.error("复制失败，请手动选择地址复制");}}
async function test(){busy.value=true;sendResult.value="";try{if(targetBot.value.transport!=='fake'&&!staffId.value.trim()&&!conversationId.value.trim())throw Error("请填写真实接收目标");const r=await imApi.ping(targetBot.value.id,{staffId:staffId.value.trim()||undefined,conversationId:conversationId.value.trim()||undefined});if(r.ok===false)throw Error(r.error||'发送失败');sendResult.value=targetBot.value.transport==='fake'?'模拟发送已记录，没有发送到真实 IM。':'测试消息已发送。';if(targetBot.value.transport==='fake')outbox.value=(await imApi.outbox()).filter(row=>row.botId===targetBot.value.id);}catch(e){message.error(e.message);}finally{busy.value=false;}}
onMounted(load);
</script>
<template><PageShell title="IM 机器人" subtitle="连接企业消息渠道，管理回调和消息发送" :loading="loading" :error="error"><template #actions><n-button v-if="can('workflow.write')" type="primary" @click="edit(null)">新建机器人</n-button></template><Panel title="机器人" :meta="`${bots.length} 个`"><n-empty v-if="!bots.length" description="还没有机器人，先配置一个渠道" class="empty-state"/><article v-for="bot in bots" :key="bot.id" class="bot-row"><div><h3>{{bot.name}} <n-tag size="small">{{bot.platform==='wecom'?'企业微信':'钉钉'}}</n-tag></h3><p class="hint">{{bot.platform==='wecom'?'CorpID':'AppKey'}}：{{bot.appKey||'未配置'}} · 绑定技能：{{skills.find(s=>s.value===bot.workflowId)?.label||bot.workflowId}}</p><p class="hint">最近回调：{{bot.lastCallbackAt?new Date(bot.lastCallbackAt).toLocaleString('zh-CN'):'尚未收到'}} · {{bot.sessionCount??0}} 个外部会话</p><div class="action-row"><code>{{callback(bot)}}</code><n-button text @click="copy(bot)">复制地址</n-button></div></div><div v-if="can('workflow.write')" class="action-row"><n-tag :type="bot.enabled?'success':'default'">{{bot.enabled?'已启用':'已停用'}}</n-tag><n-button :disabled="!bot.enabled" @click="targetBot=bot;staffId='';conversationId='';sendResult=''">测试发送</n-button><details class="more-actions"><summary>更多</summary><div class="more-menu"><n-button @click="edit(bot)">配置</n-button><n-button :loading="busy" @click="toggle(bot)">{{bot.enabled?'停用':'启用'}}</n-button><n-button type="error" @click="remove(bot)">删除</n-button></div></details></div></article></Panel>
<n-modal v-model:show="showCreate" preset="card" :title="editing?'配置机器人':'新建机器人'" style="width:680px"><n-alert v-if="editing" type="info" :bordered="false">密钥留空沿用，不会回显已有明文。</n-alert><n-form label-placement="top" class="form-grid"><n-form-item label="机器人名称" required class="full"><n-input v-model:value="draft.name" placeholder="例如：售后通知机器人"/></n-form-item><n-form-item label="平台"><n-select v-model:value="draft.platform" :disabled="!!editing" :options="platforms"/></n-form-item><n-form-item label="绑定技能"><n-select v-model:value="draft.workflowId" :options="skills"/></n-form-item><n-form-item :label="draft.platform==='wecom'?'CorpID':'AppKey'" required><n-input v-model:value="draft.appKey"/></n-form-item><n-form-item :label="draft.platform==='wecom'?'AgentId':'RobotCode'" required><n-input v-model:value="draft.robotCode"/></n-form-item><n-form-item :label="draft.platform==='wecom'?'Secret':'AppSecret'" :required="!editing"><n-input v-model:value="draft.appSecret" type="password" autocomplete="new-password"/></n-form-item><n-form-item label="回调 Token" :required="!editing"><n-input v-model:value="draft.callbackToken" type="password" autocomplete="new-password"/></n-form-item><n-form-item label="EncodingAESKey" :required="draft.platform==='wecom'&&!editing" class="full"><n-input v-model:value="draft.aesKey" type="password" autocomplete="new-password"/></n-form-item></n-form><template #footer><div class="action-row"><n-button @click="showCreate=false;draft=blank()">取消</n-button><n-button type="primary" :loading="busy" @click="save">保存机器人</n-button></div></template></n-modal>
<n-modal :show="!!targetBot" preset="card" title="发送测试消息" style="width:500px" @update:show="v=>{if(!v)targetBot=null}"><p class="hint">{{targetBot?.transport==='fake'?'当前为模拟通道，可不填写接收目标。':'会实际发送消息，请只选择一个接收目标。'}}</p><n-form label-placement="top"><n-form-item label="员工 UserID"><n-input v-model:value="staffId"/></n-form-item><n-form-item v-if="targetBot?.platform==='dingtalk'" label="群会话 ID"><n-input v-model:value="conversationId"/></n-form-item></n-form><n-alert v-if="sendResult" type="success">{{sendResult}}</n-alert><template #footer><n-button type="primary" :loading="busy" @click="test">发送测试消息</n-button></template></n-modal><Panel v-if="outbox.length" title="当前机器人模拟出站记录" style="margin-top:20px"><p v-for="(row,i) in outbox" :key="i">{{new Date(row.at).toLocaleString('zh-CN')}} · {{row.botName}} · {{row.content}}</p></Panel></PageShell></template><style scoped>.bot-row{display:flex;justify-content:space-between;gap:20px;padding:20px 0;border-bottom:1px solid var(--line);flex-wrap:wrap}.bot-row h3{font-size:16px;margin:0}.bot-row code{font-size:12px;overflow-wrap:anywhere}</style>
